result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/sbomgen.py", "content": "#!/usr/bin/env python3
"""sbomgen.py - a minimal SBOM generator.

Scans a project directory for requirements.txt and package.json manifests,
resolves each declared dependency's name/version/ecosystem, and emits
CycloneDX-shaped JSON.

Usage:
    python sbomgen.py <project-dir> [-o output.json]
    python sbomgen.py --validate <sbom-file>
"""

import argparse
import json
import os
import sys

BOM_FORMAT = "CycloneDX"
SPEC_VERSION = "1.5"
SCHEMA_VERSION = 1


# --------------------------------------------------------------------------
# Manifest parsing
# --------------------------------------------------------------------------

def parse_requirements_txt(path):
    """Parse a requirements.txt file into (name, version_or_None, raw_spec) tuples."""
    deps = []
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            # Strip environment markers / comments after whitespace.
            if " #" in line:
                line = line.split(" #", 1)[0].strip()
            name, version = _parse_pip_spec(line)
            deps.append((name, version, line))
    return deps


def _parse_pip_spec(spec):
    """Return (name, version) for a pip requirement string; version may be None."""
    name = spec.split(";")[0].strip()
    version = None
    for sep in ("==", ">=", "<=", "~=", "!=", ">", "<"):
        if sep in name:
            idx = name.index(sep)
            candidate = name[idx + len(sep):].split(",")[0].strip()
            name = name[:idx].strip()
            if candidate:
                version = candidate
            break
    return normalize_name(name, "pypi"), version


def parse_package_json(path):
    """Parse a package.json file into (name, version_or_None, raw_spec) tuples."""
    with open(path, encoding="utf-8") as fh:
        data = json.load(fh)
    deps = []
    for section in ("dependencies", "devDependencies"):
        for name, spec in sorted(data.get(section, {}).items()):
            version = None
            if isinstance(spec, str):
                stripped = spec.strip()
                if stripped.startswith("~") or stripped.startswith("^"):
                    version = stripped[1:]
                elif stripped[0].isdigit():
                    version = stripped
            deps.append((name, version, spec))
    return deps


# --------------------------------------------------------------------------
# Helpers
# --------------------------------------------------------------------------

def normalize_name(name, ecosystem_type):
    if ecosystem_type == "pypi":
        return name.replace("_", "-").lower()
    return name


def make_purl(ecosystem, name, version):
    if ecosystem == "pypi":
        return "pkg:pypi/%s@%s" % (name.lower(), version)
    # npm: scoped packages (@org/pkg) must be percent-encoded.
    encoded = name.replace("@", "%40")
    return "pkg:npm/%s@%s" % (encoded, version)


# --------------------------------------------------------------------------
# SBOM assembly
# --------------------------------------------------------------------------

def collect_components(project_dir):
    """Scan project_dir and return a deterministic list of component dicts."""
    found = []  # (ecosystem, name, version)

    req = os.path.join(project_dir, "requirements.txt")
    if os.path.isfile(req):
        for name, version, _raw in parse_requirements_txt(req):
            found.append(("pypi", name, version))

    pkg = os.path.join(project_dir, "package.json")
    if os.path.isfile(pkg):
        for name, version, _raw in parse_package_json(pkg):
            found.append(("npm", name, version))

    components = []
    for ecosystem, name, version in sorted(found, key=lambda t: (t[0], t[1])):
        resolved = version if version is not None else "unresolved"
        components.append({
            "type": "library",
            "name": name,
            "version": resolved,
            "purl": make_purl(ecosystem, name, resolved),
        })
    return components


def build_sbom(project_dir):
    return {
        "bomFormat": BOM_FORMAT,
        "specVersion": SPEC_VERSION,
        "components": collect_components(project_dir),
    }


# --------------------------------------------------------------------------
# Validation mode
# --------------------------------------------------------------------------

REQUIRED_COMPONENT_FIELDS = ("type", "name", "version", "purl")


def validate_sbom(sbom):
    errors = []
    if not isinstance(sbom, dict):
        return ["SBOM root must be a JSON object"]
    if sbom.get("bomFormat") != BOM_FORMAT:
        errors.append("missing or invalid 'bomFormat' (expected %r)" % BOM_FORMAT)
    if not sbom.get("specVersion"):
        errors.append("missing 'specVersion'")
    components = sbom.get("components")
    if not isinstance(components, list) or not components:
        errors.append("missing or empty 'components' list")
        return errors
    for i, comp in enumerate(components):
        for field in REQUIRED_COMPONENT_FIELDS:
            if not comp.get(field):
                errors.append("component[%d] missing required field %r" % (i, field))
        purl = comp.get("purl", "")
        if purl and not purl.startswith("pkg:pypi/") and not purl.startswith("pkg/npm/"):
            errors.append("component[%d] has invalid purl %r" % (i, purl))
    return errors


# --------------------------------------------------------------------------
# CLI
# --------------------------------------------------------------------------

def main(argv=None):
    parser = argparse.ArgumentParser(
        prog="sbomgen",
        description="Minimal CycloneDX-shaped SBOM generator.",
    )
    parser.add_argument(
        "--validate", metavar="FILE",
        help="validate an existing SBOM file instead of generating one",
    )
    parser.add_argument(
        "project_dir", nargs="?", default=".",
        help="project directory containing requirements.txt / package.json",
    )
    parser.add_argument("-o", "--output", help="write SBOM to this file (default: stdout)")
    args = parser.parse_args(argv)

    if args.validate:
        try:
            with open(args.validate, encoding="utf-8") as fh:
                sbom = json.load(fh)
        except (OSError, ValueError) as exc:
            print("error: cannot load SBOM: %s" % exc, file=sys.stderr)
            return 2
        errors = validate_sbom(sbom)
        if errors:
            for err in errors:
                print("invalid:", err, file=sys.stderr)
            return 1
        print("OK: SBOM is valid")
        return 0

    project_dir = args.project_dir
    if not os.path.isdir(project_dir):
        print("error: not a directory: %s" % project_dir, file=sys.stderr)
        return 2

    sbom = build_sbom(project_dir)
    text = json.dumps(sbom, indent=2)
    if args.output:
        with open(args.output, "w", encoding="utf-8") as fh:
            fh.write(text + "\n")
    else:
        print(text)
    return 0


if __name__ == "__main__":
    sys.exit(main())
